<section class="panel auth-panel"><h1><?= e($user['name']) ?></h1><p class="muted"><?= e($user['email']) ?> · Билет № <?= str_pad((string)$user['id'],5,'0',STR_PAD_LEFT) ?></p><h2>Изменить пароль</h2>
<form method="post" class="form-stack"><?= csrf_input() ?><input type="hidden" name="action" value="password"><label>Текущий пароль<input type="password" name="old_password" maxlength="72" autocomplete="current-password" required></label><label>Новый пароль<input type="password" name="password" minlength="10" maxlength="72" autocomplete="new-password" required></label><label>Повторите новый пароль<input type="password" name="password_confirm" minlength="10" maxlength="72" autocomplete="new-password" required></label><button class="button primary">Сохранить пароль</button></form></section>
